/**
 * Wissensbasis der Plattform-Hilfe: kurze, konkrete Antworten je Bereich – sofort verfügbar, ohne KI-Aufruf.
 * Wird im Chat-Build direkt genutzt und im echten Betrieb als Grundlage/Ersatz, wenn kein Sprachmodell antwortet.
 */
export type HelpTopic = { id: string; title: string; keys: RegExp; answer: string };

export const HELP_TOPICS: HelpTopic[] = [
  { id: "dashboard", title: "Dashboard lesen (Übersicht & Statistik)", keys: /dashboard|\bstart\b|operations overview|kennzahl|kpi|stundenverlauf|lead-puls|puls|preping|bestellverteilung|zeitraum|von.bis|zeitspanne|statistik|auswertung|annahmequote|auf einen blick/i, answer: "So liest du das Dashboard:\n• Zwei Reiter oben rechts: „Übersicht“ (von oben nach unten: Kennzahlen – Ausgelieferte Leads, Umsatz, Dubletten, Reklamationen, PrePing – → Bestellverteilung → Karte „Wo fließen die Leads?“ → Stundenverlauf → Lead-Puls) und „Statistik“ (ein Klick: Käufer, Lieferanten, Bestellungen, Lieferketten, Integrationen – die frühere Seite „Statistik“; beginnt mit „Auf einen Blick“: beste Annahme, Käufer mit schwacher Annahmequote, stärkster Lieferant, Zustellwege und Umsatz). Zeitraum und Kategorie gelten für beide Reiter – auch der Lead-Puls zeigt nur Leads aus dem gewählten Zeitraum und der gewählten Kategorie.\n• Oben wählst du Zeitraum (Heute, Diese Woche, Gesamt …) und Kategorie – alle Bereiche darunter beziehen sich darauf. „Eigener Zeitraum“ öffnet Von/Bis-Felder mit Schnellwahl (Letzte 7/30/90 Tage, Letzter Monat, Quartal, Jahr); die Auswahl wird gemerkt.\n• Kacheln: Ausgelieferte Leads (an Käufer übergeben), Umsatz, Dubletten, Reklamationen und PrePing abgelehnt (Käufer hat per PrePing vorab abgelehnt).\n• Stundenverlauf: Zahl über jedem Balken = Leads in dieser Stunde; roter Anteil = per PrePing abgelehnt. Klick auf einen Balken zeigt, welche Kategorie an welchen Kunden ging; „Ganzen Tag anzeigen“ listet alle Stunden.\n• Bestellverteilung: welche Bestellung wie viele Leads bekommen hat (Käufer, Lieferant, Kategorie, Weg, Geliefert, PrePing, Umsatz).\n• Lead-Puls: die neuesten Leads mit Status." },
  { id: "leads", title: "Leads", keys: /\blead(s)?\b|quick view|lead-seite|sammelaktion|import|csv|spalte|filter|leadansicht|status|hängend|haengend|dublette|fehlerhaft|zugewiesen|genehmigt|reklamiert|deaktiviert/i, answer: "Leads:\n• „Lead anlegen“ oder „Leads importieren“ (CSV mit Spaltenzuordnung, Import kann rückgängig gemacht werden).\n• Status-Reiter (Zugewiesen, Reklamiert, Fehlerhaft, Deaktiviert, Hängend, Dubletten) und „Filter“ (Kategorie, Lieferant, Zeitraum) – Filter lassen sich mit Namen speichern.\n• Spalte „Typ“ zeigt die Kategorie als Kürzel (PV, WP, FEN …); „Spalten anpassen“ blendet Spalten ein/aus.\n• Auge = Quick View (Kontakt, Fachfelder, Log, Reklamation erfassen, jetzt ausliefern). Klick auf den Namen = Lead-Seite mit allem.\n• Mehrere Leads anhaken → Sammelaktion unten (Ausliefern, Käufer zuordnen, Status setzen, Tag setzen).\nStatus: Neu = eingegangen · Genehmigt = geprüft, unverkauft · Zugewiesen = an Käufer ausgeliefert · Reklamiert = Reklamation genehmigt · Fehlerhaft = Daten ungültig · Hängend = wartet auf Liefertag/Kette · Dublette = bereits vorhanden." },
  { id: "kategorien", title: "Lead-Kategorien", keys: /kategori|sparte|fachfeld|typ\b|kürzel|farbe/i, answer: "Lead-Kategorien (Kategorien wie Photovoltaik, Wärmepumpe, Fenster, Treppenlifte, Barrierefreie Bäder, Alarmanlagen, Wintergärten, Elektrorollstühle, Rollatoren, Hörgeräte):\n• Links eine Kategorie wählen → Grundeinstellungen (Name, Kürzel, Farbe, Emoji, Preis, Mehrfachverkauf), Fachfelder (Text, Zahl, Auswahl, Ja/Nein …) und Datenharmonisierung.\n• Farbe und Emoji erscheinen überall dezent (Lead-Liste „Typ“, Dashboard-Chips und -Pillen, Karte, Quick View, Pipeline-Karten). Ohne eigenes Emoji schlägt die Software eines aus dem Namen vor („Vorschlag“).\n• „Neue Kategorie aus Spezifikation“: Parameterblatt hochladen, der Builder schlägt Fachfelder vor." },
  { id: "bestellungen", title: "Bestellungen", keys: /bestell|auftrag|liefertag|menge|leadpreis/i, answer: "Bestellungen:\n• „Bestellung anlegen“: Name, Käufer, zugelassene Lieferanten, eine oder mehrere Kategorien, Leadpreis, Menge, Liefertage/Uhrzeiten, Lieferpausen, Zusatzfilter.\n• Schritt 2 „Lieferkette ergänzen“: mehrere Abnehmer als Stops (Reihenfolge, Preis, Reklamationsfenster, Gründe, PLZ-Gebiete).\n• Bestellübersicht zeigt Fortschritt (geliefert / Menge) und Status. Leads werden automatisch passenden aktiven Bestellungen zugeordnet; „hängend“ heißt: wartet auf den nächsten Liefertag." },
  { id: "lieferkette", title: "Lieferkette (Wasserfall)", keys: /lieferkette|kette|wasserfall|stop|weitergeben|round-robin|verteilmodus|geo|bundesl/i, answer: "Lieferkette (Wasserfall): Ein Lead wird der Reihe nach an Käufer angeboten.\n• Kette je Kategorie anlegen, Stops = Käufer mit Preis, Reklamationsfenster (Stunden) und Tageslimit.\n• Reklamationsgründe je Stop auf „weitergeben“ stellen → bei genehmigter Reklamation geht der Lead an den nächsten Stop. Sind alle Stops durch, ist die Kette „erschöpft“.\n• PLZ-Gebiete/Bundesländer je Stop: nur passende Leads werden angeboten. Verteilmodus oben: Lieferketten- oder Bestellungen-Round-Robin.\n• Unter „Aktivität“ siehst du je Stop, welche Leads angeboten, angenommen oder übersprungen wurden." },
  { id: "automatisierung", title: "Automatisierung", keys: /automatis|regel|wenn|dann|sonst|aktion|auslöser|trigger/i, answer: "Automatisierung (Wenn → Dann → Sonst):\n• „Neue Automatisierung“: Auslöser (z. B. Lead erstellt, Reklamation genehmigt), Bedingungen (Feld, Operator, Wert) und Aktion (Lead freigeben, Status ändern, Kategorie ändern, Tag setzen, Webhook, E-Mail …). Optional ein SONST-Zweig.\n• Der Automatisierungsbuilder auf der Seite baut aus einem Satz eine Regel (pausiert) – danach prüfen und aktivieren.\n• „Protokoll“ zeigt jede Ausführung mit Ergebnis." },
  { id: "integrationen", title: "Integrationen & API", keys: /integration|api|schnittstelle|endpunkt|endpoint|webhook|token|builder|aroundhome|wattfox|ondialer|dialer/i, answer: "Integrationen:\n• Eingehend: Lieferanten schicken Leads per API (Token unter Benutzer → Lieferant → „Token erzeugen“; Beispiele unter Einstellungen → API-Dokumentation). Partner-Webhooks: /api/partner/wattfox, /api/partner/ondialer.\n• Ausgehend: Käufer bekommen Leads an ihren Endpunkt (Benutzer → Integration → Endpunkt, Vorlagen z. B. Aroundhome mit Sub-ID, Response-Mapping für Dublette/Ablehnung).\n• Der Integrationsbuilder auf der Seite liest Partner-Unterlagen und legt eine inaktive Verbindung an. Fehler siehst du im Lead-Log (HTTP-Status + Antwort) und unter Integrationen → Ereignisse.\nTypische Ursachen: falscher Zugangsschlüssel (401/403), falsche Feldnamen (400/422), Endpunkt nicht erreichbar." },
  { id: "reklamation", title: "Reklamationen", keys: /reklam|frist|dublette|grund|genehmig|ablehn/i, answer: "Reklamationen:\n• Intern: „Neuen Vorgang“ mit Lead, Grund, Text → genehmigen oder ablehnen. Genehmigt = Lead-Status „Reklamiert“; bei Lieferkette mit „weitergeben“ geht der Lead an den nächsten Stop.\n• Per API: Käufer sendet POST /api/reclaim mit Lead-Nummer und Grund innerhalb seiner Frist (Benutzer → Reklamation: Frist, automatisch annehmen).\n• Gründe pflegst du unter Einstellungen → Reklamationen (weitergeben ja/nein). Filter und CSV-Export gibt es auf der Seite." },
  { id: "emails", title: "E-Mails", keys: /e-mail|email|mail|smtp|willkommen|erinnerung/i, answer: "E-Mails (Kommunikation → E-Mails): Beim Anlegen eines Benutzers geht sofort eine Willkommensmail (Anmeldeadresse, Benutzername, Passwort); Erinnerungen nach 3 und 7 Tagen, solange er sich nicht angemeldet hat. Versandprotokoll mit Vorschau, „Jetzt senden“, „Abbrechen“; Vorlagen mit Platzhaltern und „Testmail an mich“. Echter Versand braucht SMTP_URL und SMTP_FROM beim Hosting – ohne SMTP wird nur simuliert." },
  { id: "email-versand-einrichten", title: "E-Mail-Versand einrichten (Brevo, Zeitüberschreitung, Testmail)", keys: /versand einrichten|e-?mail-?versand|brevo|api-?schlüssel|xkeysib|xsmtpsib|smtp-?schlüssel|testmail.*fehl|fehlgeschlagen|zeitüberschreitung|timeout|port.*gesperrt|gesperrt.*port|587|2525|465|absender einrichten|anbieter wählen/i, answer: "E-Mail-Versand einrichten (Einstellungen → E-Mail-Versand):\n• Empfohlen bei Railway und ähnlichen Hostern: Anbieter-Karte **„Brevo über HTTP“**. Dann braucht es nur den **API-Schlüssel** (in Brevo: SMTP & API → Reiter „API-Schlüssel“, beginnt mit `xkeysib-`), Absendername, Absenderadresse, Tageslimit, Häkchen „Versand einschalten“ → **Speichern** (der Knopf direkt im Abschnitt, nicht oben in der Kopfzeile) → **Testmail** an die eigene Adresse.\n• Warum HTTP: Railway und viele andere Hoster sperren die Mail-Ports (25, 465, 587, 2525) gegen Spam-Versand. Ein SMTP-Versuch läuft dort in eine Zeitüberschreitung – egal ob die Zugangsdaten stimmen. Die HTTP-Schnittstelle läuft über Port 443 wie eine normale Webseite und ist immer erreichbar.\n• Testmail sagt „Zeitüberschreitung“ oder „timeout“: Der Hoster sperrt den Mail-Port. Lösung: Anbieter auf „Brevo über HTTP“ umstellen und den API-Schlüssel eintragen.\n• Zwei verschiedene Schlüssel: SMTP = `xsmtpsib-…`, HTTP = `xkeysib-…`. Wird der falsche eingetragen, erklärt die Testmail das im Klartext.\n• Testmail sagt „Brevo 401“: Schlüssel falsch oder gelöscht – in Brevo neu erzeugen und hier eintragen. „Brevo 400: sender not valid“: Die Absenderadresse ist in Brevo nicht als Absender freigegeben (Brevo → Absender & Domains).\n• Domain prüfen: Der Knopf prüft SPF, DKIM und DMARC. Liegt das Postfach bei Google und wird über Brevo versendet, muss beides im SPF stehen: `v=spf1 include:spf.brevo.com include:_spf.google.com ~all`.\n• Posteingang (IMAP): Postfach der Absenderadresse, Port 993; bei Google `imap.gmail.com` mit einem App-Passwort aus dem Google-Konto.\n• Der Knopf „Änderungen speichern“ oben in der Kopfzeile gilt nur für System, Branding, Nutzungsbedingungen und API-Dokumentation – alle anderen Bereiche speichern über ihre eigenen Knöpfe am Abschnitt." },
  { id: "haustuer", title: "Haustür-Erfassung", keys: /haust|d2d|vertriebler|agentur|sub-id|subid|iframe|außendienst/i, answer: "Haustür-Erfassung: Vertriebler erfassen Kontakte zuerst bei uns (Schritt 1), dann im Aroundhome-iFrame (Schritt 2, Werte per Klick kopieren). Jeder Vertriebler hat eine Sub-ID von Aroundhome; ohne Sub-ID sieht er nur einen Hinweis.\n• „Zuweisung“: Kategorie (Pflicht für die Vorerfassung) und optional Käufer (dann sofort verkauft, ohne Bestellung/API).\n• „Agentur anlegen“ erzeugt einen Agenturleiter-Login, der nur seine Agentur sieht. Vertriebler anlegen = Login per E-Mail, Sub-ID gleich oder später, Sperren möglich.\n• Kennzahlen: Vorerfasst (bei uns), Bei Aroundhome, Qualifiziert, Offen, Storniert – abgeglichen je Sub-ID und Tag, Stand spätestens 15 Minuten." },
  { id: "pipeline", title: "Vertriebspipeline & Meta Ads", keys: /vertriebspipeline|pipeline|meta|facebook|instagram|kampagne|werbe|anzeige|kosten je lead|cpl|funnel|trichter|kunde geworden|gewonnen/i, answer: "Vertriebspipeline (Vertrieb → Vertriebspipeline): Leads aus Meta Ads mit Kampagne, Anzeigengruppe, Anzeige und Formular – plus jeder Schritt bis zum Kunden.\n• Einstellungen → Facebook-Verbindung: „Mit Facebook verbinden“ (Facebook-Login, braucht META_APP_ID/META_APP_SECRET beim Hosting) oder Seiten-Token einfügen. Danach kommen neue Leads über den Meta-Webhook sofort an, ohne Zapier; Kampagnen-Kennzahlen (Ausgaben, Reichweite, Klicks) werden stündlich geladen.\n• Formulare → Kategorie: welches Lead-Formular welche Lead-Kategorie bekommt.\n• Pipeline: Stufen Neu → Kontaktiert → Qualifiziert → Termin → Angebot → Kunde (oder Verloren); umbenennen/ergänzen unter Einstellungen → Stufen. Karten per Ziehen in die nächste Stufe; Klick auf eine Karte klappt sie in ihrer Spalte auf (die Spalte wird etwas breiter): oben Anrufen, nächste Stufe und die Werkzeuge (Wiedervorlage, Termin und Wert zeigen den aktuellen Stand direkt im Knopf; SMS, WhatsApp, E-Mail), darunter Infos und Notizen (mit Mikrofon) nebeneinander – alles auf einen Blick, die Karte bleibt kompakt; Schritte und Nachrichten lassen sich darunter aufklappen. Klick auf den Namen öffnet die Lead-Seite. Jeder Schritt wird mit Zeit und Person protokolliert.\n• Statistik: Kennzahlen, Funnel, Pipeline-Wert und die Tabelle „Kampagnen aus Meta“ (Budget, Ausgaben, Reichweite, Klicks, Leads, Kosten je Lead, Kunden, Kosten je Kunde) – Klick „Pipeline zeigen“ filtert das Board auf die Kampagne.\n• Reiter oben: Pipeline, Aufgaben, Termine, Statistik, Einstellungen (Stufen, Team & Ziele, Automatik, Facebook-Verbindung); bei Kaltakquise zusätzlich „Listen & Kontakte“." },
  { id: "wiedervorlagen", title: "Wiedervorlagen, Aufgaben & Termine", keys: /wiedervorlage|aufgabe|heute fällig|fällig|erledigt|verschieben|termin|kalender|einladung|ics|erinnerung|kalendereintrag/i, answer: "Wiedervorlagen & Termine (Vertriebspipeline → „Aufgaben“ und „Termine“):\n• An jeder Karte: „Wiedervorlage“ (Anrufen, E-Mail, Aufgabe, SMS, WhatsApp mit Datum/Uhrzeit, Zuständigem, Notiz). Aus dem Dialer entstehen sie automatisch: „Wiedervorlage“ → Rückruf, „Interessiert“ → „Angebot / Unterlagen schicken“, „Nicht erreicht“ → erneut versuchen (Automatik abschaltbar).\n• „Aufgaben“ (Reiter zwischen Pipeline und Termine): Überfällig, Heute, Morgen, Diese Woche – mit „Jetzt anrufen“ (Pipeline-Dialer), „Alle abtelefonieren“, Erledigt, Verschieben (morgen/3 Tage/1 Woche), Löschen. Die Karte zeigt die nächste Fälligkeit als Hinweis; Filter „Fällig“ im Board.\n• „Termin“ an der Karte: Datum, Dauer, Ort, Notiz – schiebt die Karte in die Stufe „Termin“, legt den Termin im Kalender an und schickt auf Wunsch die Einladung mit Kalendereintrag (ICS) per E-Mail. Die Erinnerung an den Kunden (E-Mail/SMS/WhatsApp, X Stunden vorher) läuft über die Automatik.\n• „Termine“: Wochenkalender (Mo–So) mit Terminen groß und Wiedervorlagen klein; Klick öffnet die Karte." },
  { id: "stufen", title: "Stufen der Pipeline anpassen", keys: /stufe|stufen|spalte|spalten|umbenennen|reihenfolge|neue stufe|stufe löschen/i, answer: "Stufen (Vertriebspipeline → Einstellungen → Stufen): Stufen umbenennen, Hinweis ändern, Reihenfolge per Pfeile, neue Stufe hinzufügen (bis 12) oder löschen – Eingang, „Kunde“ und „Verloren“ bleiben immer erhalten (umbenennbar). Gilt für alle drei Pipelines (Meta Ads, Kaltakquise, E-Mail); Leads gelöschter Stufen rutschen auf den Eingang. „Speichern“ wird erst aktiv, wenn sich etwas geändert hat; „Zurücksetzen“ verwirft die Änderung." },
  { id: "eingeschlafen", title: "Eingeschlafene Karten", keys: /eingeschlafen|schläft|keine bewegung|aufweck|aufwecken|lead-punkte|punkte|score|scoring|heiß|warm|kalt/i, answer: "Eingeschlafene Karten:\n• Eine Karte gilt als eingeschlafen, wenn X Tage (Automatik, Standard 5) nichts passiert ist – kein Stufenwechsel, keine Notiz, keine Nachricht, keine erledigte Aufgabe. Hinweis „💤 X Tage“ an der Karte, Filter „Eingeschlafen“ im Board.\n• Optional nimmt die Automatik eingeschlafene Kontakte mit E-Mail automatisch in eine Aufweck-Serie auf (einmal je Karte). Serie unter Automatik anlegen oder wählen.\n• Lead-Punkte/Scoring gibt es nicht mehr – die Karten zeigen stattdessen nur echte Hinweise: eingeschlafen, Wiedervorlage fällig, Termin, Angebotswert." },
  { id: "nachrichten", title: "SMS, WhatsApp & Einzel-E-Mail aus der Karte", keys: /\bsms\b|whatsapp|nachricht senden|einzel-e-mail|einzelmail|vorlage aus kampagne|textnachricht/i, answer: "Nachrichten aus der Karte (Vertriebspipeline → Karte öffnen → SMS / WhatsApp / E-Mail):\n• Vorlagen (Rückruf anbieten, Termin bestätigen, Terminerinnerung, Unterlagen, Angebot nachfassen, freier Text) mit Platzhaltern {{anrede}} {{nachname}} {{vorname}} {{firma}} {{termin}} {{absender}} – Vorschau vor dem Senden.\n• SMS geht über die eigene Rufnummer (Telefonie). WhatsApp: mit WhatsApp-Business-Absender (Twilio) direkt, sonst öffnet sich WhatsApp mit vorausgefülltem Text. E-Mail: freier Text oder eine E-Mail aus einer Kampagne/Vorlage im Kampagnen-Design.\n• Jede Nachricht steht im Verlauf der Karte („Nachrichten“ und „Schritte“); die erste Nachricht zieht die Karte aus „Neu“ nach „Kontaktiert“. Sperrliste wird beachtet." },
  { id: "angebotswerte", title: "Angebotswerte, Pipeline-Wert & Umsatz", keys: /angebotswert|auftragswert|wert\b|umsatz|pipeline-wert|gewichtet|abschlussquote|euro/i, answer: "Angebotswerte & Umsatz:\n• An der Karte „Wert“ (Angebots-/Auftragswert in Euro). Steht als Pille an der Karte.\n• Statistik: Pipeline-Wert (offen), gewichtet nach Stufe (Neu 10 % … Angebot 90 %), Umsatz gewonnen (Stufe „Kunde“), Abschlussquote nach Anzahl und nach Euro, Verloren, Wert je Stufe, Umsatz je Vertriebler.\n• Einstellungen → Team & Ziele: Umsatz und offener Wert je Vertriebler im gewählten Zeitraum. CSV-Export enthält die Werte." },
  { id: "team-verteilung", title: "Team: Ziele, Zählung & Verteilregeln", keys: /tagesziel|ziel\b|ziele|zählung|team|verteilregel|verteilung|reihum|regel|plz-anfang|auslastung|nicht zugeteilt|zuteilen/i, answer: "Team (Vertriebspipeline → Einstellungen → Team & Ziele):\n• Je Vertriebler: Anrufe (Dialer), erreicht, Gesprächsminuten, Termine gesetzt, Abschlüsse, Umsatz, offene Karten mit Wert, Aufgaben heute/überfällig – gegen das Tagesziel (Anrufe, Termine, Abschlüsse je Tag, direkt in der Tabelle eintragen). Zeitraum Heute / 7 Tage / 30 Tage.\n• Verteilung neuer Leads: Aus (nur von Hand), Reihum (abwechselnd) oder Nach Regeln: je Regel ein Vertriebler, PLZ-Anfänge (z. B. 6, 5), Kategorien, maximale offene Karten; erste passende Regel gewinnt, sonst reihum oder offen lassen. Gilt für neue Leads aus Meta, Listen, Lead-Finder und Posteingang ohne gewählten Vertriebler.\n• „Nicht zugeteilte jetzt verteilen“ und im Board per Mehrfachauswahl „Nach Regeln“." },
  { id: "mehrfachauswahl", title: "Suche, Filter, Mehrfachauswahl & CSV", keys: /suche|suchen|mehrfachauswahl|auswählen|markieren|mehrere karten|csv-export|export|herunterladen|excel/i, answer: "Board-Werkzeuge (Vertriebspipeline → Pipeline):\n• Suche über Name, Firma, Ort, PLZ, Telefon, E-Mail, Kampagne. Filter: Eingeschlafen, Fällig, Nicht zugeteilt.\n• „Auswählen“: Karten ankreuzen (alle sichtbaren/keine), dann Verschieben nach Stufe, Zuteilen an Vertriebler, Nach Regeln verteilen oder alle Ausgewählten anrufen (Power/Predictive-Liste).\n• „CSV“: alle Karten des aktuellen Filters (Zeitraum, Vertriebler, Kampagne/Liste) als Excel-taugliche Datei mit Stufe, Vertriebler, Angebotswert, Wiedervorlage, Termin und letzter Notiz." },
  { id: "pipeline-automatik", title: "Pipeline-Automatik: Serien, Antworten, Erinnerungen", keys: /automatik|stufe.*serie|angebot.*nachfass|nachfass-serie|anruf-ergebnis|antwort.*stufe|kontaktiert|terminerinnerung|automatisch.*serie/i, answer: "Automatik (Vertriebspipeline → Einstellungen → Automatik):\n• Eingeschlafene Karten: Tage ohne Bewegung + Aufweck-Serie.\n• Stufe → E-Mail-Serie: z. B. „Angebot“ → Nachfass-Serie (2 Mails, Ende sobald geantwortet). Entwürfe werden beim ersten Kontakt aktiv.\n• Anruf-Ergebnis → Serie/Wiedervorlage: „Interessiert“ schickt sofort die Angebots-Mail; Wiedervorlage/Nicht erreicht legen Aufgaben an (abschaltbar).\n• Antwort im Posteingang schiebt die Karte auf die gewählte Stufe (nur vorwärts, nie aus Kunde/Verloren).\n• Terminerinnerung an den Kunden per E-Mail/SMS/WhatsApp X Stunden vorher.\n• „Automatik jetzt ausführen“ prüft sofort; sonst läuft sie alle 15 Minuten im Hintergrund." },
  { id: "ki-builder", title: "KI-Vorlagen-Builder für E-Mails", keys: /ki-vorlage|ki-builder|ki vorlagen|e-mail bauen|serie bauen|serie per ki|per ki|ki-text|text erzeugen|beschreib|künstliche intelligenz|claude|generier|vorschläge|vorschreiben|vorlagen schreiben/i, answer: "KI-Vorlagen-Builder (E-Mail-Kampagnen):\n• Im Builder einer E-Mail: Reiter „KI-Vorlage“ – beschreibe in ein, zwei Sätzen, welche E-Mail du brauchst (Anlass, Zielgruppe, was der Empfänger tun soll), wähle Ziel (Termin, Rückruf, Angebot nachfassen, Infos, Aufwecken, Willkommen), Ton und Länge, optional Link für den Knopf und zweiter Betreff für den A/B-Test → „E-Mail bauen“ schreibt Betreff, Vorschautext und Bausteine; das Design bleibt. Danach wie gewohnt anpassen.\n• Im Kampagnen-Editor: „Serie per KI“ (oder „Neue Kampagne → Per KI beschreiben“) baut die ganze Serie: 2–4 E-Mails, Abstand in Tagen, Ende wenn geantwortet/geklickt/geöffnet. Jede E-Mail ist danach im Builder editierbar.\n• An der Pipeline-Karte: „KI-Text“ im Nachrichten-Fenster schreibt SMS/WhatsApp/E-Mail-Text aus einer kurzen Beschreibung.\n• Vorschläge: Der Builder schreibt Vorlagen vor – im Reiter „KI-Vorlage“ und bei „Serie per KI“ stehen fertige Vorschläge (Erstkontakt, Nachfassen nach Angebot, Aufwecken, Termin, Willkommen, Rückruf-Bitte, Infos & Unterlagen, Letzte Nachricht); ein Klick füllt nur die Beschreibung, Ziel, Ton und Länge aus – du kannst alles noch anpassen; gebaut wird erst mit „E-Mail bauen“ bzw. „Serie bauen“.\n• Vorlagen vorschreiben lassen: E-Mail-Kampagnen → Kampagnen → Knopf „Vorlagen“ oben rechts → „Vorlagen per KI schreiben“: Vorschläge ankreuzen, optional auf eine Lead-Kategorie zuschneiden (z. B. Photovoltaik) und Unterschrift angeben → fertige Vorlagen erscheinen im Vorlagen-Fenster (Knopf „Vorlagen“) und bei „Neue Kampagne → Aus Vorlage“; jede lässt sich im Builder anpassen.\n• Der Builder liefert immer eine ganze E-Mail: Überschrift, Anrede + Absätze, Aufzählung, Knopf, Grußformel, Signatur. Antwortet die KI zu kurz (nur eine Zeile), fragt der Builder einmal nach und ergänzt fehlende Teile aus dem Gerüst – der Hinweis nach dem Bauen zeigt Bausteine und Wörter.\n• Mit KI-Schlüssel (ANTHROPIC_API_KEY beim Hosting) schreibt die KI; ohne Schlüssel kommt ein regelbasierter Entwurf, der sich genauso anpassen lässt. In der Chat-Vorschau fragt der Browser einmal nach der KI-Freigabe." },
  { id: "telefon-nachtragen", title: "Dialer für Leads ohne Telefonnummer", keys: /keine telefonnummer|ohne nummer|nummer nachtragen|telefon nachtragen|dialer fehlt|anruf.*posteingang|posteingang.*anruf|aus der signatur/i, answer: "Dialer für Leads aus dem Posteingang / ohne Nummer:\n• Beim Anlegen eines Leads aus dem Posteingang wird die Telefonnummer aus der E-Mail-Signatur erkannt und vorausgefüllt („aus der E-Mail erkannt“); bei bestehenden Leads ohne Nummer gibt es das Feld „Telefon nachtragen“.\n• In der Pipeline hat jede Karte den Telefon-Knopf – ohne Nummer ist er gestrichelt: Klick fragt die Nummer ab, speichert sie an der Karte (Verlauf „Kontaktdaten“) und startet sofort den Anruf. In der geöffneten Karte heißt der Knopf dann „Nummer + Anrufen“." },
  { id: "posteingang", title: "Posteingang: Antworten lesen, KI-Einordnung, Filter", keys: /posteingang|antworten lesen|antwort.*kampagne|kampagne.*filter|filter.*kampagne|abholen|imap|ungelesen|prüfen|einordnung|einordnen|abwesenheit|interessiert|zeitraum.*posteingang|posteingang.*zeitraum|datum.*filter|filter.*datum/i, answer: "Posteingang (E-Mail-Kampagnen → erster Reiter ganz links, öffnet sich zuerst):\n• Oben die Ordner: Alle, Ungelesen, Antworten (auf Serien), Nicht zugeordnet (Absender, die noch keinem Lead in der Pipeline zugeordnet sind), Archiv, Gesperrt – jeweils mit Anzahl. Rechts daneben die Kampagnen-Auswahl („Alle Kampagnen“ oder eine Serie, dann erscheint ein Hinweis mit „Filter entfernen“) und „Aktualisieren“ (liest das Postfach).\n• Links die schmale Liste: Suchfeld oben, Nachrichten nach Heute / Gestern / Diese Woche / Älter gruppiert, mit Absender-Kürzel, Betreff, Vorschau und kleinen Merkern (Antwort auf welche Kampagne, Stufe in der Pipeline, Nicht zugeordnet, Abgemeldet, Gesperrt). Ungelesene haben einen farbigen Balken am Rand.\n• Rechts die Nachricht groß: Absender, Betreff, Hinweise (z. B. „In der Pipeline: Termin bei Taner“ als Link), darunter die Knöpfe Als Lead in Pipeline / Stufe setzen, Antworten, Sperren bzw. Entsperren, Archivieren. Das Lead-Formular klappt direkt unter den Knöpfen auf (Telefon aus der Signatur wird erkannt).\n• KI prüft jede Antwort beim Aktualisieren: Beschwerde, Abmeldewunsch, Interessiert, Frage oder Abwesenheitsnotiz. Eindeutige Beschwerden und Abmeldungen werden automatisch gesperrt (Hinweis „automatisch gesperrt“ mit Zitat an der Nachricht, Unterliste Beschwerden/Abmeldungen in der Sperrliste, Serie gestoppt); unsichere Fälle landen im Ordner „Prüfen“ mit den Knöpfen „Sperren“ und „Ist in Ordnung“. „Interessiert“ wird als Notiz an die Pipeline-Karte geschrieben, Abwesenheitsnotizen nur markiert. Schalter unter Einstellungen → E-Mail-Versand → „KI prüft jede Antwort“ (an/aus, automatisch sperren oder nur markieren). Ein Fehlgriff: „Entsperren“.\n• Sortierung (ganz links in der Leiste): Neueste zuerst, Älteste zuerst oder nach Einordnung – „Interesse zuerst“ gruppiert die Liste von Interessiert über Frage, Sonstiges, Abwesenheitsnotiz und Abmeldewunsch bis Beschwerde, „Beschwerde zuerst“ umgekehrt; jede Gruppe zeigt ihre Anzahl, die Wahl wird gemerkt.\n• Filter daneben: KI-Einordnung (Beschwerde, Abmeldewunsch, Interessiert, Frage, Abwesenheitsnotiz, Sonstiges, Automatisch gesperrt, Zu prüfen, Ohne Einordnung), Zeitraum (Gesamt, Heute, Gestern, Letzte 7 Tage, Letzte 30 Tage, eigener Von/Bis) und Kampagne – alle kombinierbar; „Filter entfernen“ setzt die Filter zurück.\n• Antwortfeld ganz unten; Strg + Enter sendet. „Antworten“ springt dorthin.\n• Auf dem Handy: erst die Liste, nach dem Antippen die Nachricht mit „Zurück zur Liste“.\n• „Aktualisieren“ liest das Postfach (Einstellungen → E-Mail-Versand → IMAP)." },
  { id: "werbung-ordner", title: "E-Mails landen im Werbung-Ordner oder im Spam", keys: /werbung|promotions|spam|junk|landet nicht im posteingang|zustellbarkeit|nicht angekommen|kommt nicht an|posteingang des empfängers|reiter werbung/i, answer: "E-Mails landen bei Gmail unter „Werbung“ oder im Spam:\n• Woran Gmail Werbung erkennt: Logo-Bild, farbiger Knopf, Kasten-Layout, ein Zählpixel für Öffnungen und Links, die über eine fremde Adresse umgeleitet werden. Genau das hat eine Kampagnen-Mail standardmäßig.\n• Lösung: Im Builder unter „Design“ den Schalter **„Persönlich senden“** einschalten. Dann geht die E-Mail ohne Logo, ohne Kasten, ohne farbigen Knopf (wird ein Textlink) und ohne Messung raus – sie sieht aus wie von Hand geschrieben und landet viel öfter im normalen Posteingang. Für Kaltakquise ist das die bessere Wahl; Öffnungs- und Klickraten gibt es dann allerdings nicht mehr.\n• Was sonst hilft: kurz schreiben, keine Werbesprache („GRATIS!!!“, viele Ausrufezeichen), höchstens ein Link, keine Bilder, Absendername als echter Mensch (z. B. „Taner von Tanesco Digital“). SPF, DKIM und DMARC müssen grün sein (Einstellungen → E-Mail-Versand → Domain prüfen).\n• Am Anfang langsam versenden: die ersten Tage 20–30 Mails, dann steigern. Ein frischer Absender, der sofort hunderte Mails schickt, wird aussortiert.\n• Antworten sind das stärkste Signal: Sobald jemand antwortet, landen weitere Mails an diese Person im Posteingang.\n• An die eigene Adresse zu testen führt in die Irre – Gmail ist bei Mails misstrauisch, die scheinbar von einem selbst kommen. Lieber an eine fremde Adresse testen." },
  { id: "kontakte-pipeline", title: "Kontakte aus der E-Mail-Akquise in die Pipeline übernehmen", keys: /pipeline übernehmen|in die pipeline|nicht in der pipeline|nur e-?mail|pushen|übernehmen.*pipeline|tauchen nicht auf|erscheinen nicht|stufe wählen|welche stufe/i, answer: "Listen, die du **im Kampagnen-Editor** hochlädst, landen bewusst **nicht** sofort in der Vertriebspipeline – sonst wäre das Board nach jedem Upload voll mit Adressen, die noch niemand angefasst hat.\n• Diese Kontakte stehen unter E-Mail-Kampagnen → Kontakte und sind dort als „nur E-Mail“ gekennzeichnet. E-Mail-Serien erreichen sie ganz normal.\n• Sollen sie aufs Board: in der Spalte ganz links ankreuzen (oder oben alle auf einmal), dann die **Stufe** wählen (Neu, Kontaktiert, Termin …) und „In die Vertriebspipeline übernehmen“ klicken. Die Kontakte landen immer in der Pipeline **„E-Mail-Kampagne“** (Vertriebspipeline → Quelle E-Mail-Kampagne), in genau dieser Stufe. Eine Verteilung an Vertriebler gibt es hier nicht – das passiert in der Pipeline.\n• Wer schon in der Pipeline ist, wird nicht doppelt übernommen (der Knopf meldet das).\n• **Anklicken:** Jede Zeile öffnet die Lead-Seite. **Löschen:** das ✕ am Zeilenende löscht einen Kontakt, ausgewählte Kontakte löscht der rote Knopf „Löschen“ – Kunden bleiben erhalten." },
  { id: "email-kontakte", title: "Kontakte der E-Mail-Akquise (eigene Lead-Liste)", keys: /kontakte.*kampagne|lead-?liste|eigene liste|wer steckt|wer ist in der kampagne|was ist passiert|reaktion|geöffnet.*liste|übersicht.*kontakte|akquise-?liste/i, answer: "Kontakte (E-Mail-Kampagnen → Reiter „Kontakte“): die eigene Lead-Liste der E-Mail-Akquise – getrennt von den Leads, die verkauft werden.\n• Je Zeile ein Kontakt mit: Name, Firma, E-Mail, aus welcher Liste er kommt, in welchen Kampagnen er steckt, was zuletzt passiert ist, wie viele Mails er bekommen hat, seine Stufe in der Pipeline, der Vertriebler und das Anlage-Datum.\n• „Zuletzt“ zeigt die stärkste Reaktion: Geantwortet vor Geklickt vor Geöffnet vor Gesendet; dazu Abgemeldet und Unzustellbar (Bounce). Daneben steht das Datum.\n• Filterleiste darunter mit Anzahl je Reaktion – ein Klick zeigt nur diese Gruppe, ein zweiter hebt den Filter auf.\n• Oben: Suche (Name, Firma, E-Mail, Ort, Liste), Liste, Kampagne und Vertriebler. „Filter entfernen“ setzt alles zurück.\n• Klick auf den Namen öffnet die Lead-Seite mit dem ganzen Verlauf: E-Mails, Notizen, Aufgaben, Anrufe.\n• Hinweis: Wer in keiner Kampagne steckt, steht unter „Noch nichts“ – das sind frisch hochgeladene Kontakte." },
  { id: "gesendet", title: "Gesendet: verschickte E-Mails ansehen und filtern", keys: /gesendet|gesendete|verschickt|versendet|was wurde gesendet|ausgang|postausgang|sent/i, answer: "Gesendet (E-Mail-Kampagnen → Posteingang → Ordner „Gesendet“):\n• Zeigt alles, was rausgegangen ist: Kampagnen-Mails aus den Serien, Antworten, die du im Posteingang geschrieben hast, und Einzel-E-Mails aus einer Pipeline-Karte.\n• Filter oben: Art (Alle, Kampagnen, Antworten, Einzeln – jeweils mit Anzahl), Kampagne, Zeitraum (Gesamt, Heute, Letzte 7 Tage, Letzte 30 Tage) und ein Suchfeld über Adresse, Betreff und Kampagnenname.\n• Jede Zeile zeigt Betreff, Empfänger, Kampagne bzw. Absender und die Uhrzeit. Ist eine Mail fehlgeschlagen oder nur simuliert, steht das als roter Hinweis daneben.\n• **Vorschau:** Ein Klick auf die Zeile klappt die E-Mail so auf, wie sie rausging (Kampagnen-Mails werden aus dem Schritt und den Empfängerdaten nachgebaut).\n• **Tracking je Mail:** Unter jeder Kampagnen-Mail stehen drei Marken – Geöffnet, Geklickt, Geantwortet – jeweils mit Uhrzeit (oder „Nicht geöffnet“ usw.). Dazu ein Reaktions-Filter über der Liste: Geöffnet, Geklickt, Geantwortet, Noch nicht geöffnet, Unzustellbar, Abgemeldet – mit Zahlen.\n• Der Name des Empfängers ist verlinkt und öffnet die Lead-Seite." },
  { id: "posteingang-aufraeumen", title: "Posteingang: nur bekannte Kontakte holen, aufräumen, eigenes Kampagnen-Postfach", keys: /aufräumen|aufraeumen|alte mails|fremde mails|newsletter im posteingang|rechnungen im posteingang|nur bekannte|alles geladen|lädt alle|eigenes postfach|kampagnen-?postfach|vertrieb@|absender übernehmen|absender auf bestehende/i, answer: "Der Posteingang soll nur Antworten auf deine Kampagnen zeigen – nicht dein ganzes Postfach.\n• **Schalter „Nur Antworten von bekannten Kontakten holen“** (Einstellungen → E-Mail-Versand → IMAP, standardmäßig an): Beim Abgleich werden nur Mails von Kampagnen-Empfängern und Leads geladen. Rechnungen, Newsletter und Fremde werden übersprungen (der Abgleich meldet, wie viele).\n• **Aufräumen** (E-Mail-Kampagnen → Posteingang → Knopf „Aufräumen“): „Nur Fremde entfernen“ löscht alle Mails ohne Lead und ohne Kampagne – z. B. alles, was vor dem Umzug auf ein eigenes Postfach mitgeladen wurde. „Alles entfernen“ leert den Posteingang komplett; Sperrliste und „Gesendet“ bleiben.\n• **Eigenes Kampagnen-Postfach** (empfohlen): z. B. vertrieb@ deiner Domain anlegen, in den E-Mail-Einstellungen als Absender, „Antwort an“ und IMAP-Benutzer eintragen. Dann landen dort nur Kampagnen-Antworten.\n• **Absender auf bestehende Kampagnen übernehmen** (E-Mail-Einstellungen, unter den Absenderfeldern): schreibt den gespeicherten Absender in alle vorhandenen Kampagnen – sonst behalten laufende Kampagnen ihre alte Adresse. Neue Kampagnen nehmen den Absender automatisch." },
  { id: "pipeline-kontakte", title: "Vertriebspipeline: Reiter „Kontakte“ und Karten löschen", keys: /kontakte.*pipeline|pipeline.*kontakte|liste statt karten|alle kontakte der pipeline|karte löschen|karten löschen|lead löschen|leads löschen|aus der pipeline entfernen|mehrere löschen/i, answer: "Vertriebspipeline:\n• **Reiter „Kontakte“**: alle Kontakte der gewählten Pipeline (Meta Ads, Kaltakquise oder E-Mail-Kampagne) als Liste – auch ohne E-Mail-Adresse – mit Telefon, Ort, Herkunft (Liste oder Meta-Kampagne), letzter E-Mail-Reaktion, Stufe und Vertriebler. Filter: Suche, Liste, E-Mail-Kampagne, Stufe, Vertriebler, Reaktion. Klick auf die Zeile öffnet die Lead-Seite.\n• **Auswahl**: ankreuzen → „Stufe setzen“, „Zuteilen an“ oder „Löschen“ für alle markierten Kontakte.\n• **Karten löschen**: Karte aufklappen → Papierkorb oben rechts in der Karte; oder im Board „Auswählen“ → mehrere Karten ankreuzen → „Löschen“ in der Leiste. Gelöscht werden nur Vertriebskontakte samt Verlauf, Aufgaben und Notizen – Verkaufs-Leads bleiben (die löscht man auf der Leads-Seite). Das lässt sich nicht rückgängig machen.\n• Angeklickte Karten und die aktive Pipeline oben sind im hellen Design rot, im dunklen lila hervorgehoben." },
  { id: "stufen-je-pipeline", title: "Jede Pipeline mit eigenen Stufen", keys: /eigene stufen|stufen je pipeline|stufen pro pipeline|pipeline gestalten|individuell gestaltbar|stufen ändern|stufen anpassen|standard-?stufen|stufen zurücksetzen/i, answer: "Jede der drei Pipelines (Meta Ads, Kaltakquise, E-Mail-Kampagne) kann eigene Stufen haben:\n• Vertriebspipeline → Pipeline oben wählen → Einstellungen → „Stufen“. Dort steht, ob die Pipeline eigene Stufen hat oder noch die Standard-Stufen nutzt.\n• Oben rechts im Editor wählst du, wofür du speicherst: „Nur für diese Pipeline“ (Standard) oder „Als Standard für alle Pipelines“ – der Standard gilt für jede Pipeline, die keine eigenen Stufen hat.\n• „Standard nutzen“ verwirft die eigenen Stufen einer Pipeline wieder. Karten in Stufen, die es danach nicht mehr gibt, rutschen auf den Eingang.\n• Eingang, „Kunde“ und „Verloren“ bleiben in jeder Pipeline erhalten. Verschieben, Lead-Seite, Kontakte-Reiter und Automatik richten sich immer nach den Stufen der Pipeline, zu der ein Kontakt gehört." },
  { id: "termine-aufgaben", title: "Termine & Aufgaben in der Vertriebspipeline", keys: /aufgaben|wiedervorlage|termine|terminkalender|kalender|fällig|überfällig/i, answer: "Vertriebspipeline → Reiter „Termine & Aufgaben“: oben der Wochenkalender mit Terminen und Wiedervorlagen (Klick öffnet die Karte), darunter die Aufgaben nach Fälligkeit – überfällig, heute, morgen, diese Woche – mit Anrufen, Erledigen und Verschieben. Die Zahl am Reiter zeigt, wie viele Aufgaben heute fällig sind. Einen eigenen Reiter „Aufgaben“ gibt es nicht mehr." },
  { id: "signatur-anhaenge", title: "Signatur und Anhänge bei Antworten aus dem Posteingang", keys: /signatur|footer.*antwort|unterschrift|anhang|anhänge|datei anhängen|dateien anhängen|pdf mitschicken|angebot mitschicken|attachment/i, answer: "Antworten aus dem Posteingang (und freie E-Mails aus einer Pipeline-Karte) bekommen automatisch deine **Signatur**:\n• Einstellungen → E-Mail-Versand → „Signatur für Antworten“: Grußformel, Name, Position, Telefon, E-Mail, Webseite; Haken für Logo und für Firma + Adresse (die kommen aus Einstellungen → Branding → Fußzeile). Rechts siehst du live, wie es beim Empfänger aussieht. Haken „aktiv“ weg = keine Signatur.\n• **Anhänge**: Im Antwortfeld unten „Anhang“ klicken (oder mehrere Dateien auf einmal wählen). Bis zu 5 Dateien, je höchstens 7 MB, zusammen 15 MB. Vor dem Senden lassen sich einzelne wieder entfernen. Im Ordner „Gesendet“ steht bei der Antwort, welche Dateien mitgingen.\n• Kampagnen-Mails nutzen weiterhin die Fußzeile aus dem Builder – die Signatur gilt nur für persönliche Antworten und Einzel-E-Mails." },
  { id: "glocke", title: "Glocke: Was ist auf der Plattform passiert? (Tagesverlauf)", keys: /glocke|benachrichtigung|mitteilung|verlauf der plattform|was ist passiert|tagesverlauf|aktivität|protokoll|wer hat was gemacht|roter punkt/i, answer: "Die Glocke oben rechts zeigt, was auf der Plattform passiert ist – nicht als Flut einzelner Meldungen, sondern als **Tagesverlauf**:\n• Je Tag eine Zeile mit Zusammenfassung, z. B. „Heute · 120 neue Kontakte · 14 Anrufe · 2 Leads verkauft“. Klick auf den Tag klappt die Arten auf (Anrufe, neue Leads, Gespräche abgehört, E-Mails gesendet, Antworten, Bestellungen, Reklamationen, Karten verschoben …), Klick auf eine Art zeigt die einzelnen Einträge mit Uhrzeit, Details und Lead-Nummer (klickbar).\n• Mitgeschrieben wird: Listen-Uploads (mit Zahlen), neue Leads (Meta Ads, Haustür, Posteingang, Test), Anrufe aus dem Dialer samt Ergebnis, abgehörte Aufzeichnungen (sobald der Player startet), Gesprächsbewertungen, verkaufte Leads (Auslieferung an einen Käufer), Bestellungen, Reklamationen, Karten-Verschiebungen in der Pipeline, Übernahmen aus der E-Mail-Akquise, gesendete Kampagnen-E-Mails (je Kampagne zusammengezählt), Antworten im Posteingang, Kampagnenstarts und rückgängig gemachte Uploads.\n• Die Zahl an der Glocke zeigt, wie viele Einträge seit deinem letzten Öffnen dazugekommen sind (gemerkt in diesem Browser). Die Glocke lädt sich jede Minute von selbst nach." },
  { id: "upload-verlauf", title: "Upload-Verlauf: was wurde wann hochgeladen, rückgängig machen", keys: /upload-?verlauf|verlauf.*upload|rückgängig|zurücknehmen|versehentlich hochgeladen|falsche liste|wieder löschen|wer hat hochgeladen|wann hochgeladen/i, answer: "Upload-Verlauf (Vertriebspipeline → Kaltakquise → „Listen & Kontakte“, und E-Mail-Kampagnen → „Kontakte“):\n• Jeder Upload steht dort mit Datum, Uhrzeit, Listenname, wer ihn gemacht hat und woher er kam (Kaltakquise oder E-Mail-Kampagne).\n• Daneben die Zahlen: wie viele Kontakte neu angelegt, wie viele vorhandene aktualisiert wurden – und wie viele davon es noch gibt.\n• **Rückgängig** entfernt genau die Kontakte, die bei diesem Upload **neu** entstanden sind. Kontakte, die dabei nur ergänzt wurden, bleiben – die gab es ja vorher schon. Kunden bleiben ebenfalls erhalten. Vor dem Löschen kommt eine Rückfrage mit der Anzahl.\n• Ein zurückgenommener Upload bleibt im Verlauf stehen, grau und mit Datum – damit nachvollziehbar bleibt, was passiert ist.\n• Hinweis: Lädst du einen Kontakt, den es schon gibt, in einer neuen Liste hoch, wechselt er in diese neue Liste – sonst würde er in der Zielgruppe der neuen Kampagne fehlen." },
  { id: "listen-ansehen", title: "Hochgeladene Listen ansehen", keys: /liste ansehen|listen ansehen|was ist in der liste|inhalt der liste|wer bekommt|empfänger sehen|kontakte der liste|liste prüfen|liste anschauen/i, answer: "Listen ansehen:\n• In der Kaltakquise-Pipeline: Vertriebspipeline → „Kaltakquise“ → Reiter „Listen & Kontakte“. Unter jeder Liste steht der Knopf „Ansehen“ – er klappt eine Tabelle mit allen Kontakten auf: Name, Firma, Telefon, E-Mail, Ort, Stufe und die Zusatzspalten aus der Datei. Oben rechts ein Suchfeld.\n• Vorschau mit echten Daten: Sobald eine Zielgruppe steht, zeigen die Vorschauen im Ablauf und im Builder die E-Mail mit den Daten des ersten Kontakts statt mit „Max Muster“ – so siehst du vor dem Versand, ob die Platzhalter stimmen. Im Builder lässt sich oben über „Anzeigen mit“ ein anderer Kontakt wählen.\n• Im Kampagnen-Editor: Zielgruppe „Liste“ wählen – darunter stehen alle hochgeladenen Listen mit Anzahl der Kontakte und wie viele davon eine E-Mail-Adresse haben (nur die bekommen die Serie). Ein Klick wählt die Liste als Zielgruppe, „Ansehen“ zeigt die Kontakte, „Löschen“ entfernt die Liste.\n• Liste löschen (im Kampagnen-Editor oder unter „Listen & Kontakte“): Die Kontakte dieser Liste werden mitgelöscht, samt Aufgaben, Notizen und Nachrichten. **Kunden bleiben erhalten** – sie verlieren nur die Zuordnung zur Liste. Rückfrage vor dem Löschen; rückgängig machen geht nicht.\n• Unter der Tabelle stehen die Platzhalter dieser Liste, z. B. {{branche}} – die kannst du im Builder in Betreff und Text einsetzen." },
  { id: "dubletten-upload", title: "Keine doppelten Kontakte beim Hochladen", keys: /doppelt|dublette|zweimal|mehrfach hochgeladen|nochmal hochladen|aktualisieren statt|überschreiben|gleiche liste nochmal/i, answer: "Doppelte Kontakte beim Hochladen (Einstellungen → System → „Keine doppelten Kontakte beim Hochladen“):\n• Ist der Schalter an (Standard), wird ein Kontakt, den es schon gibt, beim nächsten Hochladen nur **aktualisiert**: leere Felder werden ergänzt, Zusatzspalten dazugeschrieben, Liste und Tags angehängt. Es entsteht kein zweiter Eintrag.\n• Erkannt wird ein Kontakt an der E-Mail-Adresse oder der Telefonnummer.\n• Vorhandene Angaben werden nie überschrieben: Steht an der Karte schon eine Firma, bleibt sie stehen. Die Änderung steht im Verlauf der Karte.\n• Ist der Schalter aus, werden bekannte Kontakte beim Hochladen einfach übersprungen (wie früher).\n• Nach dem Hochladen sagt die Meldung, wie viele neu angelegt und wie viele aktualisiert wurden." },
  { id: "tags-filter", title: "Tags vergeben und danach filtern", keys: /tag|tags|schlagwort|etikett|markieren|kategorisieren|filtern nach tag|tag filter/i, answer: "Tags:\n• Beim Hochladen einer Liste gibt es das Feld „Tags“ – mehrere mit Komma trennen, z. B. „PV, Hessen“. Jeder Kontakt der Liste bekommt diese Tags, zusätzlich zum automatischen Tag „Liste: …“.\n• In den E-Mail-Kampagnen: Zielgruppe „Tag“ wählen – dann bekommen genau die Kontakte mit diesem Tag die Serie.\n• Eine Lead-Kategorie ist beim Hochladen nicht nötig; Tags reichen zum Sortieren." },
  { id: "sperrliste", title: "Sperrliste: Bounces, Abmeldungen, Posteingang sperren", keys: /sperrliste|sperren|gesperrt|entsperren|bounce|unzustellbar|abmeld|abgemeldet|unsubscribe|beschwerde|spam|protokoll|unterliste/i, answer: "Sperrliste (E-Mail-Kampagnen → „Sperrliste“):\n• Alles, was bounct, sich abmeldet oder im Posteingang gesperrt wird, landet automatisch hier – als Protokoll mit Grund, Quelle (z. B. Kampagne, Abmelde-Link, Mail-Anbieter, Posteingang) und Datum. Unterlisten: Alle, Bounces, Abmeldungen, Beschwerden, Posteingang, Manuell – mit Zählern, Suche und CSV-Export.\n• Gesperrte Adressen bekommen keine Kampagnen-E-Mails mehr (egal in welcher Zielgruppe), laufende Serien werden sofort gestoppt. „Aufheben“ gibt eine Adresse wieder frei.\n• Posteingang → „Sperren“: setzt den Absender auf die Sperrliste (Unterliste „Posteingang“) und verschiebt alle seine Nachrichten in den Filter „Gesperrt“; neue Mails von ihm landen direkt dort. „Entsperren“ macht beides rückgängig.\n• Antworten wie „bitte keine E-Mails mehr“, „unsubscribe“, „aus dem Verteiler nehmen“ erkennt der Posteingang automatisch: Adresse → Unterliste „Abmeldungen“, Serie gestoppt, Hinweis „Abmeldung erkannt“ an der Nachricht.\n• Beschwerden in Antworten („Das ist Spam“, „Hören Sie auf“, Drohung mit Anwalt/Meldung) erkennt die KI beim Aktualisieren des Posteingangs und sperrt die Adresse automatisch (Unterliste „Beschwerden“, mit Zitat und Prozentwert); ist sie sich nicht sicher, liegt die Nachricht im Posteingang unter „Prüfen“. Abschaltbar unter Einstellungen → E-Mail-Versand.\n• Bounces/Beschwerden vom Anbieter: Knopf beim Empfänger in der Kampagne oder Webhook des Mail-Anbieters (POST /api/mail/bounce, Secret MAIL_WEBHOOK_SECRET); Abmeldungen auch über den Abmelde-Link in jeder E-Mail." },
  { id: "trennung", title: "Leads zum Verkauf ≠ Vertriebskontakte", keys: /trennung|getrennt|vertriebskontakt|verkaufs-?lead|leads zum verkauf|nichts mit .* zu tun|vermischt|gemischt|unterschied.*pipeline|pipeline.*leads-seite|leads-seite.*pipeline/i, answer: "Zwei getrennte Welten:\n• Leads zum Verkauf (Lead-Operations: Leads, Bestellungen, Lieferkette, Rohdaten, Callcenter, Statistik, Dashboard) – die Anfragen, die Tanesco an Partner verkauft.\n• Vertriebskontakte (Vertriebspipeline, E-Mail-Kampagnen, Posteingang, Kaltakquise-Listen, Meta-Ads-Formulare) – Betriebe, die selbst Kunde werden sollen.\n• Beide liegen technisch getrennt (Kennzeichen „verkauf“/„vertrieb“) und tauchen nie in der jeweils anderen Ansicht auf: ein Verkaufs-Lead landet nicht in der Pipeline oder in einer E-Mail-Serie, ein Vertriebskontakt nie in Bestellungen, Lieferketten, Callcenter-Kampagnen oder Statistiken. Zielgruppen der E-Mail-Kampagnen („alle“, Liste, Stufe, Tag) bestehen nur aus Vertriebskontakten; der Posteingang verknüpft Absender nur mit Vertriebskontakten.\n• Die globale Suche zeigt beide getrennt: „Leads“ (Verkauf) und „Vertriebskontakte“ (Pipeline – öffnet direkt die Lead-Seite)." },
  { id: "email-verlauf", title: "E-Mail-Verlauf am Lead (was vorher per Mail besprochen wurde)", keys: /e-?mail-?verlauf|mailverlauf|mail-?verlauf|vorher besprochen|was besprochen|vorgeschichte|früherer schriftverkehr|schriftverkehr|konversation|unterhaltung per mail|verlauf.*mail|mail.*verlauf/i, answer: "E-Mail-Verlauf: Jeder Lead in der Vertriebspipeline zeigt alles, was mit seiner E-Mail-Adresse per Mail hin- und herging – wie ein Chat, älteste oben.\n• Was drinsteht: eingegangene Mails aus dem Posteingang (links, mit KI-Einordnung), unsere Antworten aus dem Posteingang, Einzel-E-Mails aus der Karte und der Versand aus E-Mail-Serien (rechts).\n• Vorgeschichte: Wird aus einer Nachricht im Posteingang ein Lead angelegt (oder in die Pipeline übernommen), hängen automatisch alle früheren Mails dieses Absenders und unsere Antworten darauf am Lead. Eine grüne Marke „Als Lead angelegt“ zeigt, was davor schon besprochen wurde; oben steht „n E-Mails wurden schon vor dem Anlegen ausgetauscht“.\n• Wo: In der aufgeklappten Karte die Zeile „E-Mail-Verlauf n“ (zeigt die letzten drei, „ältere anzeigen“ holt den Rest, Link zur Lead-Seite). Auf der Lead-Seite der Reiter „E-Mail-Verlauf“ mit Tagestrennern; lange Mails lassen sich mit „Ganze E-Mail“ aufklappen.\n• Antworten aus dem Posteingang werden dafür gespeichert – auch wenn es noch keinen Lead gibt; sie werden beim Anlegen nachträglich zugeordnet." },
  { id: "lead-seite", title: "Lead-Seite in der Pipeline (alles bearbeiten)", keys: /lead-?seite|lead-?fenster|leadfenster|ausführlich|alle infos|name klicken|klick auf den namen|neues fenster|bearbeiten|stammdaten|kontakt löschen|löschen|neuer tab/i, answer: "Lead-Seite (Vertriebspipeline): Klick auf den Namen einer Karte (oder der Pfeil-Knopf in der aufgeklappten Karte) wechselt auf eine eigene Seite – nur dort lassen sich alle Daten bearbeiten. Ein Klick auf die Karte selbst klappt sie dagegen breit in ihrer Spalte auf.\n• Kopf: Kategorie (Emoji + Kürzel), Quelle, Name, Firma, Ort; Stufe und Vertriebler direkt umstellbar; „Neuer Tab“ öffnet die Seite in einem eigenen Browser-Tab (nicht in der Chat-Vorschau).\n• Aktionen: Anrufen (ohne Nummer: erst eintragen), Wiedervorlage, Termin, Wert, SMS, WhatsApp, E-Mail, nächste Stufe, Verloren / Wieder aufnehmen.\n• Links: Stammdaten bearbeiten (Anrede, Vorname, Nachname, Firma, Telefon, E-Mail, PLZ, Ort, Kategorie) → „Speichern“ (jede Änderung steht im Verlauf als „Kontaktdaten“); Herkunft; Angebot & Termine; ganz unten „Kontakt löschen“ (mit Rückfrage – nur Vertriebskontakte).\n• Rechts: Verlauf, Notizen (tippen oder einsprechen), Aufgaben & Termine (erledigen), Nachrichten, Anrufe (mit Gesprächsnotiz), E-Mail-Serien, Posteingang.\n• „← Vertriebspipeline“, ✕ oder Escape führen zurück zum Board; der Link ?lead=… lässt sich teilen." },
  { id: "mikrofon", title: "Mikrofon: Notizen einsprechen", keys: /mikro|mikrofon|einsprechen|diktier|spracheingabe|sprach|aufnahme funktioniert nicht|mic\b/i, answer: "Notizen einsprechen (Lead-Seite → Notizen → Mikrofon):\n• Beim ersten Klick fragt der Browser nach der Mikrofon-Freigabe – „Zulassen“ wählen. Danach einfach sprechen; der Text erscheint live, Pausen sind egal (die Erkennung läuft weiter, bis du das Mikrofon wieder anklickst). „Speichern“ legt die Notiz mit 🎤 ab.\n• Funktioniert in Chrome, Edge und Safari (Spracherkennung des Browsers, Deutsch) – Firefox kann das nicht. Die Erkennung braucht eine Internetverbindung.\n• Freigabe verweigert? Schloss-Symbol in der Adresszeile → Mikrofon → Zulassen, dann erneut auf das Mikrofon klicken.\n• In der eingebetteten Chat-Vorschau sperrt der Browser das Mikrofon im Rahmen: dann öffnet der Mikrofon-Knopf ein kleines eigenes Fenster zum Einsprechen – dort einmal die Freigabe erteilen; der Text landet trotzdem live in der Notiz. Pop-ups für die Seite müssen erlaubt sein." },
  { id: "email-details", title: "A/B-Test, Versandfenster, Sperrliste, Vorlagen", keys: /a\/b|ab-test|betreff b|variante|versandfenster|zeitzone|werktags|bounce|unzustellbar|beschwerde|spam|sperrliste|gesperrt|vorlage|vorlagen|duplizieren|kopie|link.*geklickt|bestimmter link/i, answer: "E-Mail-Kampagnen – Details:\n• A/B-Betreff: im Ablauf bei einer E-Mail „Betreff B“ ausfüllen; Anteil B per Regler (10–90 %). Empfänger werden aufgeteilt, die Auswertung zeigt Öffnungs- und Klickrate je Variante und den Gewinner.\n• Versandfenster: nur an gewählten Wochentagen zwischen von/bis in einer Zeitzone senden – fällige Mails warten bis zum nächsten Fenster.\n• Wenn-Abfrage „Link geklickt“ kann auf einen bestimmten Link eingeschränkt werden (z. B. /termin).\n• Sperrliste (eigener Reiter „Sperrliste“): siehe Thema „Sperrliste“ – Unterlisten Bounces, Abmeldungen, Beschwerden, Posteingang, Manuell mit Grund, Quelle und Datum.\n• Vorlagen: Kampagne „Als Vorlage“ ablegen; die Vorlagen öffnen sich über den Knopf „Vorlagen“ in der Kopfzeile der Kampagnen (kein eigener Reiter), dort „Kampagne daraus anlegen“; „Kopie“ dupliziert eine Kampagne ohne Empfänger. „Neue Kampagne“ bietet Kaltakquise, Nachfassen nach Angebot und Aufwecken." },
  { id: "email-kampagnen", title: "E-Mail-Kampagnen & Kaltakquise", keys: /e-mail-kampagne|email-kampagne|kaltakquise|liste hochladen|listen hochladen|e-?mail-?liste|excel|xlsx|hochladen|anrufkampagne|power|predictive|newsletter|serie|nachfassen|builder|geöffnet|geklickt|posteingang|antwort|imap/i, answer: "Kaltakquise & E-Mail-Kampagnen (Menü Vertrieb):\n• Listen hochladen: Vertriebspipeline → oben „Kaltakquise“ → Reiter „Listen & Kontakte“ → Excel- oder CSV-Datei auswählen oder hineinziehen (Kopfzeile mit Vorname, Nachname, Firma, Telefon, E-Mail, PLZ, Ort; erstes Tabellenblatt). Name der Liste und Zuteilung (Taner/Francesco 50/50, nur einer, später) wählen → „In die Pipeline übernehmen“. Kontakte landen in der Pipeline unter „Neu“; Dubletten werden übersprungen. Für eine E-Mail-Serie zu dieser Liste: E-Mail-Kampagnen → Neue Kampagne → Zielgruppe „Liste“ → Liste wählen (nur Kontakte mit E-Mail-Adresse, Sperrliste wird abgezogen). Kürzer: Direkt im Kampagnen-Editor unter Zielgruppe „Liste“ steht „Neue Liste hochladen“ – Excel/CSV hineinziehen oder „Datei wählen“, Name prüfen, „Hochladen und als Zielgruppe wählen“ – die Liste ist sofort als Zielgruppe gesetzt (Kontakte landen gleichzeitig in der Kaltakquise-Pipeline).\n• Spalten zuordnen: Nach dem Auswählen der Datei zeigt „Spalten zuordnen“ jede Spalte mit Beispielwert und einer Auswahl: Standardfeld (Anrede, Vorname, Nachname, Firma, Telefon, E-Mail, PLZ, Ort, Notizen), „Platzhalter {{spaltenname}}“ oder „nicht übernehmen“. Bekannte Überschriften werden automatisch erkannt, unbekannte Spalten (z. B. Branche, Anzahl Mitarbeiter) werden automatisch zu Platzhaltern. Jede Änderung wertet die Datei sofort neu aus.\n• Platzhalter aus der Liste: Zusatzspalten stehen als {{branche}}, {{anzahl_mitarbeiter}} usw. zur Verfügung (Umlaute werden umgeschrieben, Leerzeichen zu _). Im Builder zeigt die Leiste „Platzhalter einfügen“ alle festen Platzhalter ({{anrede}}, {{vorname}}, {{nachname}}, {{name}}, {{firma}}, {{stadt}}, {{email}}, {{abmelden}}) und grün die aus der gewählten Liste – ein Klick fügt sie in das zuletzt benutzte Textfeld ein (Betreff, Vorschautext, Baustein). Die Vorschau zeigt Beispielwerte aus der Liste. Beim Versand werden sie je Empfänger gefüllt – auch in Einzel-E-Mails, SMS und WhatsApp aus der Karte. Die Felder stehen außerdem auf der Lead-Seite unter „Aus der Liste“ und in der aufgeklappten Karte. Dann „Anrufen“ im Modus Manuell, Power oder Predictive – die Anrufkampagne läuft unter „Telefonie“ wie im Callcenter.\n• Versandfenster: Jede neue Kampagne sendet standardmäßig nur werktags zu Arbeitszeiten, 7:30–17:00 Uhr (Berlin) – **freitags nur bis 13:00 Uhr**; fällige E-Mails außerhalb warten bis zum nächsten Fenster. Im Editor unter „Versandfenster“ lassen sich Tage, Uhrzeiten und Zeitzone ändern. Darunter steht „Abweichende Zeiten je Tag“: dort bekommt jeder Wochentag eigene Uhrzeiten (z. B. Freitag 7:30–13:00), „zurücksetzen“ nimmt die Ausnahme wieder weg. „Auf Standard zurücksetzen“ stellt alles wieder her, das Häkchen aus = rund um die Uhr.\n• E-Mail-Kampagnen: „Neue Kampagne“ bringt eine fertige Serie mit: 1. E-Mail → 72 Stunden warten → Wenn geöffnet → Dann Nachfass-E-Mail A, Sonst Nachfass-E-Mail B. Oben fasst „So läuft es“ den ganzen Ablauf in einer Zeile zusammen. Die Schritte hängen an einer Linie; das „+“ auf der Linie klappt die Auswahl auf (E-Mail, Warten, Wenn … dann, Ende). „Warten“ hat Schnellwahl (1 Tag, 2 Tage, 3 Tage, 1 Woche). „Wenn … dann“ steht als Satz („Wenn der Empfänger … geöffnet hat / einen Link geklickt hat / geantwortet hat“), darunter zwei Zweige: links „Dann“ (trifft zu), rechts „Sonst“ – jeder Zweig zeigt im Kopf kurz, was darin passiert (z. B. „1 E-Mail → Ende“). Jede E-Mail im Ablauf zeigt eine echte Vorschau (die fertige Mail, verkleinert), in schmalen Zweigen kompakt – Klick auf die Vorschau öffnet den Builder.\n• Builder: Bausteine (Überschrift, Text, Aufzählung, Bild, Knopf, Linie, Signatur) plus Design (Farben, Schrift, Logo, Fußzeile) mit Live-Vorschau und Testmail.\n• Kopieren: Im Ablauf hat jede E-Mail und jede Wartezeit ein Kopier-Symbol neben dem Papierkorb – die Kopie hängt sofort dahinter, bei einer E-Mail mit allen Bausteinen. Im Builder hat jeder Baustein ebenfalls ein Kopier-Symbol neben den Pfeilen; die Kopie erscheint direkt darunter. Eine Verzweigung lässt sich nicht kopieren, weil zwei ganze Zweige daran hängen.\n• Verschieben: Neben dem Kopier-Symbol steht die Auswahl „Verschieben …“. Sie bietet jede Stelle im Ablauf an: ganz an den Anfang, hinter einen bestimmten Schritt oder in den Dann- bzw. Sonst-Zweig einer Verzweigung. Der Rest des Ablaufs bleibt verbunden – der Vorgänger zeigt danach auf den Nachfolger.\n• Links in der Fußzeile: Im Design unter „Fußzeile“ stehen Knöpfe für Webseite, Terminlink und E-Mail. Eigener Text geht so: [Termin vereinbaren](https://cal.com/tanesco) – vorn der sichtbare Text, hinten die Adresse. Eine blanke Adresse wie tanescodigital.de wird von selbst anklickbar. Anschrift, Webseite und Terminlink stehen unter Einstellungen → Branding; neue Kampagnen übernehmen sie von selbst, für bestehende gibt es dort den Knopf „Auf bestehende Kampagnen übernehmen“. Bausteine verschieben: am Griff links ziehen und an jeder Stelle ablegen (auch ganz nach oben), oder mit den Pfeilen bzw. „Ganz nach oben“; der verschobene Baustein leuchtet kurz auf. Platzhalter wie {{vorname}} oder {{firma}}.\n• Drei Pipelines unter Vertriebspipeline: Meta Ads, Kaltakquise und E-Mail-Kampagne (Empfänger der Serien; Antworten setzen den Lead automatisch auf „Kontaktiert“).\n• Posteingang (Reiter in E-Mail-Kampagnen): holt Antworten per IMAP ab (Einstellungen → E-Mail-Versand → Antworten erkennen), zeigt Antworten auf Serien, unbekannte Anfragen und Ungelesenes; Absender mit „Als Lead in Pipeline“ in die Meta-Ads- oder Kaltakquise-Pipeline übernehmen (Stufe, Vertriebler), direkt antworten, archivieren.\n• Zielgruppe: Alle Kontakte mit E-Mail, eine Liste, eine Pipeline-Stufe oder ein Tag. Nach „Starten“ laufen die Schritte automatisch (Zeitplaner); Öffnungen und Klicks werden über Pixel/Links gemessen, „Fällige Schritte jetzt ausführen“ stößt sofort an. Echter Versand braucht SMTP_URL/SMTP_FROM." },
  { id: "benutzer", title: "Benutzer & Kundenbereich", keys: /benutzer|nutzer|käufer|kunde|lieferant|team|rolle|als benutzer einloggen|ansicht|freigabe/i, answer: "Benutzer: „Neuer Benutzer“ (Käufer, Lieferant, Admin, Vertriebler) mit Passwort. Auf der Detailseite: Reiter „Ansicht“ (welche Menüpunkte der Kunde sieht), „Integration“ (Endpunkt, Vorlagen, Preset), „Reklamation“ (Frist, Token), „Lieferant“ (Token, Rückgabe-Webhook), „Aktivität“. „Als Benutzer einloggen“ zeigt dir seinen Kundenbereich (gelbes Banner, „Zurück zum Admin“). Teams gruppieren Benutzer, Kooperationen sind externe Partner." },
  { id: "tags", title: "Tags", keys: /\btags\b|lead-tag|tag setzen|tags-seite|marker|label/i, answer: "Tags sind farbige Marker für Leads: unter „Tags“ anlegen/umfärben/umbenennen; am Lead (Quick View) per Klick setzen; im Filter und in Automatisierungen („Lead-Tag setzen“) nutzbar. Die Tags-Seite zeigt Nutzung, letzte Verwendung und Beispiel-Leads." },
  { id: "darstellung", title: "Darstellung (Hell/Dunkel)", keys: /hell|dunkel|dark|light|darstellung|design|farbe|automatisch|sonne|system|modus/i, answer: "Darstellung: Sonne/Mond-Symbol oben rechts → Hell, Dunkel, Automatisch (hell am Tag, dunkel nach Sonnenuntergang – Standort einmal freigeben) oder Wie System (folgt deinem Gerät). Die Wahl bleibt im Browser gespeichert. Logo und Primärfarbe stellst du unter Einstellungen → Branding ein." },
  { id: "pipeline-dialer", title: "Dialer in der Vertriebspipeline", keys: /pipeline.*(anruf|dialer|wählen|waehlen|telefon)|(anruf|dialer|wählen|waehlen).*pipeline|karte anrufen|stufe abtelefonieren|abtelefonieren|direkt anrufen/i, answer: "Dialer in der Vertriebspipeline:\n• Karte öffnen → „Anrufen“: der Anruf läuft unten im Dialer-Feld (Klingelt → Verbunden → Auflegen), ohne die Pipeline zu verlassen. Telefon-Symbol im Spaltenkopf = ganze Stufe als Wählliste: Manuell (du startest jeden Anruf), Power (nach jedem Ergebnis sofort der nächste) oder Predictive (mehrere Nummern gleichzeitig, angenommene Gespräche werden durchgestellt). Die Liste wird als Kampagne „Pipeline: …“ angelegt; Besetzt/Keine Antwort/Anrufbeantworter werden als „Nicht erreicht“ verbucht und nach 4 Stunden erneut versucht (höchstens 3-mal).\n• Nach dem Gespräch: Ergebnis wählen (Verkauft/Termin, Interessiert, Wiedervorlage, Nicht erreicht, Kein Interesse, Falsche Nummer, Nicht mehr anrufen) – die Karte rückt passend vor (Verkauft → Termin, Interessiert → Qualifiziert, Wiedervorlage → Kontaktiert, Kein Interesse → Verloren; nie zurück).\n• Automatische Gesprächsnotiz: Schalter „Auto-Notiz“ oben im Dialer; die Notiz erscheint an der Karte, im Verlauf und unter Telefonie → Anrufe.\n• Voraussetzung: eine Rufnummer (Telefonie → Rufnummern); mit Twilio hört der Agent über das Browser-Headset, in der Simulation läuft alles ohne Audio." },
  { id: "gespraechsnotiz", title: "Automatische Gesprächsnotiz", keys: /gesprächsnotiz|gespraechsnotiz|automatische notiz|auto-notiz|zusammenfassung|notiz.*anruf|anruf.*notiz|transkript|mikrofon|spracheingabe|einsprechen/i, answer: "Automatische Gesprächsnotiz (alle Dialer):\n• Nach jedem Gespräch entsteht eine Notiz am Kontakt – Zusammenfassung, wichtige Punkte, nächster Schritt, Ergebnis und Dauer. Mit KI-Schlüssel (ANTHROPIC_API_KEY) fasst die KI das Transkript zusammen, sonst gibt es eine Kurzfassung; ohne Aufzeichnung/Einwilligung besteht die Notiz aus Ergebnis, Dauer und Agenten-Notiz.\n• Ein/Aus: Schalter „Auto-Notiz“ direkt im Dialer (Telefonie → Wählen und im Pipeline-Dialer), bei der Anrufkampagne in der Kaltakquise, je Kampagne (Telefonie → Kampagnen) und als Standard unter Telefonie → Einstellungen.\n• Die Notiz steht an der Pipeline-Karte (blau, „automatisch aus dem Gespräch“), im Verlauf des Leads und unter Telefonie → Anrufe (Spalte Notiz).\n• Spracheingabe für eigene Notizen braucht Mikrofonzugriff: In der eingebetteten Chat-Vorschau sperrt der Browser das Mikrofon; in der installierten Version (https) fragt er einmal nach der Freigabe." },
  { id: "aufzeichnung", title: "Aufzeichnung & Einwilligung", keys: /aufzeichn|aufnahme|einwilligung|ansage|201 stgb|ohne abfrage|recording/i, answer: "Aufzeichnung (Telefonie → Einstellungen → Aufzeichnung & Einwilligung):\n• Standard: Ansage zu Gesprächsbeginn oder Klick des Agenten „Einwilligung erteilt“ – erst dann wird aufgezeichnet und bewertet.\n• Schalter „Ohne Einwilligungsabfrage aufzeichnen“: Aufzeichnung ab Gesprächsbeginn ohne Ansage und ohne Klick – nur wenn die Einwilligung bereits anders vorliegt (z. B. im Lead-Formular bestätigt). Wichtig: In DE/AT/CH ist das Aufzeichnen ohne Einwilligung aller Beteiligten strafbar (§ 201 StGB); die Software dokumentiert solche Aufzeichnungen als „ohne Abfrage“.\n• „Gespräche aufzeichnen und bewerten“ aus = keine Aufzeichnung, Gesprächsnotizen dann nur aus den Anrufdaten." },
  { id: "callcenter", title: "Callcenter", keys: /rohdaten|telefon|anruf|dialer|gespräch|kampagne|twilio|bewertung/i, answer: "Callcenter: „Rohdaten“ = Listen hochladen und Kontakte in Leads umwandeln. „Telefonie“ = Kampagnen, Anrufe (Twilio-Zugang unter Telefonie), Gesprächsergebnis setzen. „Gespräche“ = Aufzeichnungen/Transkripte mit KI-Bewertung nach Kriterien." },
  { id: "einstellungen", title: "Einstellungen", keys: /einstellung|konfiguration|branding|logo|domain|zahlung|rechnung|passwort|dublettenschutz|api-dokumentation/i, answer: "Einstellungen: Profil (Darstellung), System (Dublettenschutz, Verteilreihenfolge), Rechnung & Rechtliches, API-Dokumentation (Beispielaufrufe), Integrationen, Passwort, Branding (Logo hochladen, Primärfarbe), E-Mail, Domain, Reklamationen (Gründe), Zahlung, Abonnement, Affiliate, Nutzungsbedingungen. Oben links „← Zurück“." },
  { id: "support", title: "Support", keys: /support|hilfe|kontakt|whatsapp|problem|fehler|funktioniert nicht/i, answer: "Hilfe: Unter „Support“ erreichst du das Tanesco-Team per WhatsApp oder E-Mail, siehst Anfragen deiner Kunden und den Plattformtest in sechs Schritten. Für einen Fehler bitte Seite, Klick und den Text aus dem Lead-Log oder Protokoll mitschicken." },
];

const normalize = (text: string) => text.toLowerCase().replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss");

/** Beste Antwort aus der Wissensbasis – mehrere Treffer werden kurz kombiniert. */
export function helpAnswer(question: string, context?: { page?: string | null; failedEvents?: number }): string {
  const q = question.trim();
  const scored = HELP_TOPICS.map((topic) => { const matches = q.match(new RegExp(topic.keys.source, "gi")) ?? []; return { topic, score: matches.length }; }).filter((entry) => entry.score > 0).sort((a, b) => b.score - a.score);
  if (!scored.length && context?.page) { const pageTopic = HELP_TOPICS.find((topic) => topic.keys.test(context.page ?? "")); if (pageTopic) scored.push({ topic: pageTopic, score: 1 }); }
  const picked = scored.slice(0, 2).map((entry) => entry.topic);
  const parts: string[] = [];
  if (!picked.length) {
    const pageTopic = context?.page ? HELP_TOPICS.find((topic) => topic.keys.test(context.page ?? "")) : undefined;
    if (pageTopic) parts.push(`Du bist gerade im Bereich „${context?.page}“ – ${pageTopic.answer}`);
    else parts.push(`Dazu habe ich keinen passenden Eintrag. Die Plattform gliedert sich in Dashboard, Leads, Lead-Kategorien, Bestellungen, Lieferkette, Automatisierung, Tags, Reklamationen, Callcenter, Vertriebspipeline (Meta Ads), Haustür-Erfassung, Benutzer, Integrationen, E-Mails, Support und Einstellungen. Frag zum Beispiel: „Wie funktioniert die Lieferkette?“ oder „Was bedeutet Status hängend?“.`);
  } else for (const topic of picked) parts.push(topic.answer);
  if (context?.failedEvents) parts.push(`Hinweis: Aktuell gibt es ${context.failedEvents} fehlgeschlagene Integrationsereignisse – Details unter „Integrationen“.`);
  return parts.join("\n\n");
}
export const normalizeQuestion = normalize;
